import { useClientId, useCopyPasteStyles, useDeviceType } from "@blocks/hooks";
import { useBlockProps } from "@wordpress/block-editor";
import { withSelect } from "@wordpress/data";
import { Fragment, useMemo } from "@wordpress/element";
import { EditProps } from "blocks/types";
import classnames from "classnames";
import React, { useEffect } from "react";
import { useBlockStyle } from "../../hooks";
import { EMPTY_ARRAY } from "../../utils";
import "../assets/sass/blocks/category/style.scss";
import InspectorControls from "./components/InspectorControls";
import { __ } from "@wordpress/i18n";

interface CategoryObject {
	id: number;
	name: string;
	slug: string;
	isCurrentPost?: boolean;
	displayName?: string;
}

interface Props extends EditProps<any> {
	categories: Array<CategoryObject>;
	posts: Array<any>;
	currentPost: any;
	currentPostCategories: number[];
}

const Edit: React.ComponentType<Props> = (props) => {
	const {
		className,
		attributes: { category, hideOnDesktop },
		setAttributes,
		categories,
		currentPost,
		currentPostCategories,
	} = props;

	const { clientId } = useClientId(props);
	const { deviceType } = useDeviceType();
	const { CopyPasterStyleBlockControl } = useCopyPasteStyles();

	const { Style } = useBlockStyle({
		blockName: "category",
		clientId,
		attributes: props.attributes,
		deviceType,
	});

	useEffect(() => {
		if (
			!category &&
			currentPostCategories &&
			currentPostCategories.length > 0 &&
			categories &&
			categories.length > 0
		) {
			const firstPostCategory = currentPostCategories.find((catId) =>
				categories.some((cat) => cat.id === catId)
			);

			if (firstPostCategory) {
				setAttributes({ category: firstPostCategory });
			}
		}
	}, [category, currentPostCategories, categories, setAttributes]);

	const isCurrentPostCategory = useMemo(() => {
		return (
			currentPostCategories &&
			category &&
			currentPostCategories.includes(parseInt(category.toString()))
		);
	}, [currentPostCategories, category]);

	const enhancedCategories = useMemo(() => {
		if (!categories || !currentPostCategories) return categories;

		return categories.map((cat) => ({
			...cat,
			isCurrentPost: currentPostCategories.includes(cat.id),
			displayName: currentPostCategories.includes(cat.id)
				? `${cat.name} (Current Post)`
				: cat.name,
		}));
	}, [categories, currentPostCategories]);

	const allCurrentPostCategories = useMemo(() => {
		if (!categories || !currentPostCategories) return [];
		return categories.filter((cat) =>
			currentPostCategories.includes(cat.id)
		);
	}, [categories, currentPostCategories]);

	const classNames = classnames(
		`mzb-category mzb-category-${clientId}`,
		className,
		hideOnDesktop && "magazine-blocks-hide-on-desktop"
	);

	const blockProps = useBlockProps({ className: classNames });

	return (
		<Fragment>
			<InspectorControls
				attributes={props.attributes}
				setAttributes={setAttributes}
				categories={enhancedCategories}
				currentPostCategories={currentPostCategories}
			/>
			<CopyPasterStyleBlockControl withBlockControls />
			<Style />
			<div {...blockProps}>
				{currentPost && (
					<>
						{allCurrentPostCategories.length > 0 && (
							<div className="mzb-category-list">
								{allCurrentPostCategories.map((cat, index) => (
									<span
										key={cat.id}
										className="mzb-category-item"
									>
										{cat.name}
									</span>
								))}
							</div>
						)}
						{allCurrentPostCategories.length === 0 && (
							<p>{__("Category", "magazine-blocks")}</p>
						)}
					</>
				)}
			</div>
		</Fragment>
	);
};

// @ts-ignore
export default withSelect((select, props) => {
	const { getEntityRecords, getEditedEntityRecord } = select("core");
	const { getCurrentPostType, getCurrentPostId } = select("core/editor");

	const {
		attributes: { category },
	} = props;

	const currentPostId = getCurrentPostId();
	const currentPostType = getCurrentPostType();
	const post = getEditedEntityRecord(
		"postType",
		currentPostType,
		currentPostId
	);

	const allCategories =
		getEntityRecords("taxonomy", "category", { per_page: -1 }) ??
		EMPTY_ARRAY;

	const postCategoryIds = post?.categories ?? EMPTY_ARRAY;

	return {
		categories: allCategories,
		currentPost: post,
		currentPostCategories: postCategoryIds,
	};
})(Edit);
