import apiFetch from "@wordpress/api-fetch";
import {
	GlobalColorStyle,
	GlobalStyles,
	GlobalTypographyStyle,
} from "../types";
import { debounceAsync, deepClone, isEqual, localized, _set } from "../utils";
import { get, registerMiddleware, useSharedState } from "./useSharedState";

registerMiddleware("global-styles", (value, next) => {
	next(value);

	new GlobalStylesProcessor(value).process();
	if (isEqual(value, localized.configs["global-styles"])) return;
	const debouncedApiFetch = debounceAsync(apiFetch, 2500);
	debouncedApiFetch({
		path: "magazine-blocks/v1/settings",
		method: "POST",
		data: {
			"global-styles": JSON.stringify({
				...value,
				_modified: new Date().toISOString(),
			}),
		},
	}).catch(() => {});
});

