import { Icon } from "@blocks/components";
import { cn } from "@blocks/utils";
import { InnerBlocks } from "@wordpress/block-editor";
import { BlockSaveProps } from "@wordpress/blocks";
import React from "react";
import dynamicClassNames from "../../../../utils/dynamic-classnames";
import metadata from "./../../block.json";

/**
 * Frozen pre-migration save function for section block (apiVersion 1).
 *
 * @param {BlockSaveProps<any>} props Block properties.
 * @return {React.JSX.Element} Save element.
 */
const Save: React.ComponentType<BlockSaveProps<any>> = (props) => {
	const {
		attributes: {
			clientId,
			container,
			cssID,
			className,
			overlay,
			height,
			align,
			topSeparator,
			bottomSeparator,
			orientation,
			justification,
			alignment,
		},
	} = props;

	const responsiveClassNames = dynamicClassNames({
		orientation,
		justification,
		alignment,
	});

	return (
		<div
			id={cssID ?? undefined}
			className={cn(
				`mzb-section mzb-section-${clientId}`,
				className,
				align && `align${align}`
			)}
		>
			{overlay && <div className="mzb-overlay" />}
			{topSeparator &&
				topSeparator.topSeparatorIcon &&
				topSeparator.topSeparatorIcon !== "none" && (
					<span className="mzb-top-separator">
						<Icon
							type="frontendIcon"
							name={topSeparator.topSeparatorIcon}
						/>
					</span>
				)}
			<div
				className={cn(
					{ "mzb-container": container === "contained" },
					{ "mzb-container-fluid": container === "stretched" }
				)}
			>
				<div
					className={cn(
						`mzb-section-inner${
							"fit-to-screen" === height
								? " mzb-height-fit-to-screen"
								: ""
						}`,
						...Object.values(responsiveClassNames)
					)}
				>
					<InnerBlocks.Content />
				</div>
				{bottomSeparator &&
					bottomSeparator.bottomSeparatorIcon &&
					bottomSeparator.bottomSeparatorIcon !== "none" && (
						<span className="mzb-bottom-separator">
							<Icon
								type="frontendIcon"
								name={bottomSeparator.bottomSeparatorIcon}
							/>
						</span>
					)}
			</div>
		</div>
	);
};

const v1 = {
	apiVersion: 1,
	attributes: {
		...metadata.attributes,
		orientation: {
			type: "object",
		},
		justification: {
			type: "object",
		},
		alignment: {
			type: "object",
		},
		blockPadding: {
			type: "object",
			default: {
				dimension: 1,
				desktop: {
					left: 15,
					right: 15,
					unit: "px",
				},
			},
			style: [
				{
					selector: "{{WRAPPER}} { padding: {{VALUE}}; }",
				},
			],
		},
	},
	supports: metadata.supports,
	save: Save,
};

export default v1;
