import { cn } from "@blocks/utils";
import { InnerBlocks } from "@wordpress/block-editor";
import { BlockSaveProps } from "@wordpress/blocks";
import React from "react";
import metadata from "./../../block.json";

/**
 * Frozen pre-migration save function for column block.
 *
 * @param {BlockSaveProps<any>} props Block properties.
 * @return {React.JSX.Element} Save element.
 */
const Save: React.ComponentType<
	BlockSaveProps<{
		clientId: string;
		className?: string;
		cssID?: string;
	}>
> = (props) => {
	const {
		attributes: { clientId, className, cssID },
	} = props;

	return (
		<div
			id={cssID ?? undefined}
			className={cn(`mzb-column mzb-column-${clientId}`, className)}
		>
			<div className="mzb-column-inner">
				<InnerBlocks.Content />
			</div>
		</div>
	);
};

const v1 = {
	apiVersion: 1,
	attributes: {
		...metadata.attributes,
	},
	supports: metadata.supports,
	save: Save,
};

export default v1;
