import { RichText, useBlockProps } from "@wordpress/block-editor";
import { BlockSaveProps } from "@wordpress/blocks";
import React from "react";
import { cn } from "../../utils";

const Save: React.ComponentType<BlockSaveProps<any>> = (props) => {
	const {
		attributes: { cssID, clientId, className, text, typography },
	} = props;

	const blockProps = useBlockProps.save({
		id: cssID ?? undefined,
		className: cn(
			`mzb-paragraph mzb-paragraph-${clientId}`,
			typography?._className,
			className
		),
	});

	if (RichText.isEmpty(text)) {
		return null;
	}

	return <p {...blockProps}>{<RichText.Content value={text} />}</p>;
};

export default Save;
